export const multiStepRetrievalRefinement = async (query, memoryModule) => {
  let refinedResults = [];
  let currentContext = query;

  for (let i = 0; i < 3; i++) { // Iterative refinement loop
    const results = await memoryModule.retrieveEmbeddings(currentContext);
    refinedResults = results.filter(result => result.confidence > 0.75);

    if (refinedResults.length === 0) break;

    currentContext = refinedResults.map(r => r.content).join(' ');
  }

  return refinedResults;
};